	@Test
	void leftDeepSeedCacheReusesOnlyExactOrderedHypergraphSearches() {
		PackedJoinEnumerator.LeftDeepOrderCache cache = new PackedJoinEnumerator.LeftDeepOrderCache();
		PackedJoinHypergraph first = chain(4);
		PackedJoinHypergraph equivalent = chain(4);

		int[] unconstrained = cache.resolve(first, 4, 0);
		int[] reused = cache.resolve(equivalent, 4, 0);
		int[] constrained = cache.resolve(equivalent, 4, 0b0011);
		int[] extensions = PackedDphypEnumerator.singletonExtensions(first);
		int[] anchoredAtZero = cache.resolve(first, extensions, 4, 0b0011, 0);
		int[] anchoredAtOne = cache.resolve(first, extensions, 4, 0b0011, 1);

		assertSame(unconstrained, reused, "an exact structural search must reuse its immutable seed order");
		assertEquals(0b0011, (1 << constrained[0]) | (1 << constrained[1]));
		assertSame(constrained, cache.resolve(first, 4, 0b0011));
		assertEquals(0, anchoredAtZero[0]);
		assertEquals(1, anchoredAtOne[0]);
		assertSame(anchoredAtZero, cache.resolve(equivalent,
				PackedDphypEnumerator.singletonExtensions(equivalent), 4, 0b0011, 0));
		assertEquals(4, cache.searchCount(), "prefix and first-node constraints are part of the exact search key");
	}

